import json

def solve_puzzle():
    houses = [0, 1, 2, 3]  # 0-based indices for houses 1..4

    categories = {
        "Name": ["Peter", "Arnold", "Alice", "Eric"],
        "Flower": ["roses", "daffodils", "carnations", "lilies"],
        "Hobby": ["photography", "painting", "cooking", "gardening"],
        "Pet": ["dog", "fish", "bird", "cat"],
        "Color": ["red", "yellow", "green", "white"],
        "HouseStyle": ["craftsman", "colonial", "ranch", "victorian"]
    }

    # Create list of variables (category, value)
    variables = []
    for cat, vals in categories.items():
        for v in vals:
            variables.append((cat, v))

    # Helper to get position if assigned
    def get_pos(assign, cat, val):
        return assign.get((cat, val), None)

    # Constraint checker
    def constraints_ok(assign):
        # Helper for equality and order constraints
        def eq(a_cat, a_val, b_cat, b_val):
            pa = get_pos(assign, a_cat, a_val)
            pb = get_pos(assign, b_cat, b_val)
            if pa is not None and pb is not None:
                return pa == pb
            return True

        def neq_pos(cat, val, bad_pos):
            p = get_pos(assign, cat, val)
            if p is not None:
                return p != bad_pos
            return True

        def right_of(a_cat, a_val, b_cat, b_val):
            pa = get_pos(assign, a_cat, a_val)
            pb = get_pos(assign, b_cat, b_val)
            if pa is not None and pb is not None:
                return pa > pb
            return True

        # Clue 1: The person in a Craftsman-style house is Arnold.
        if not eq("Name", "Arnold", "HouseStyle", "craftsman"):
            return False

        # Clue 2: The person who loves the rose bouquet is somewhere to the right of Peter.
        if not right_of("Flower", "roses", "Name", "Peter"):
            return False

        # Clue 3: The photography enthusiast is the person who owns a dog.
        if not eq("Hobby", "photography", "Pet", "dog"):
            return False

        # Clue 4: The person who loves a bouquet of daffodils is not in the fourth house.
        if not neq_pos("Flower", "daffodils", 3):
            return False

        # Clue 5: The person who loves the rose bouquet is the person whose favorite color is red.
        if not eq("Flower", "roses", "Color", "red"):
            return False

        # Clue 6: The person in a Craftsman-style house is in the second house.
        craftsman_pos = get_pos(assign, "HouseStyle", "craftsman")
        if craftsman_pos is not None and craftsman_pos != 1:
            return False

        # Clue 7: Eric is the person residing in a Victorian house.
        if not eq("Name", "Eric", "HouseStyle", "victorian"):
            return False

        # Clue 8: The person with an aquarium of fish is the person who loves white.
        if not eq("Pet", "fish", "Color", "white"):
            return False

        # Clue 9: The person who loves cooking is somewhere to the right of the person whose favorite color is red.
        if not right_of("Hobby", "cooking", "Color", "red"):
            return False

        # Clue 10: The person who loves white is the person who loves a carnations arrangement.
        if not eq("Color", "white", "Flower", "carnations"):
            return False

        # Clue 11: The person who loves white is somewhere to the right of the person who enjoys gardening.
        if not right_of("Color", "white", "Hobby", "gardening"):
            return False

        # Clue 12: The person who loves a bouquet of daffodils is the person who loves yellow.
        if not eq("Flower", "daffodils", "Color", "yellow"):
            return False

        # Clue 13: The person living in a colonial-style house is the person whose favorite color is red.
        if not eq("HouseStyle", "colonial", "Color", "red"):
            return False

        # Clue 14: The person who has a cat is Eric.
        if not eq("Pet", "cat", "Name", "Eric"):
            return False

        return True

    # Backtracking with MRV
    def solve():
        assignment = {}
        used_by_cat = {cat: set() for cat in categories}
        solutions = []

        # Pre-assign nothing; constraints will enforce relationships

        def possible_positions(var):
            cat, val = var
            poss = []
            for pos in houses:
                if pos in used_by_cat[cat]:
                    continue
                assignment[var] = pos
                used_by_cat[cat].add(pos)
                if constraints_ok(assignment):
                    poss.append(pos)
                used_by_cat[cat].remove(pos)
                del assignment[var]
            return poss

        def backtrack():
            if len(assignment) == len(variables):
                # Found a complete assignment
                solutions.append(assignment.copy())
                return True  # Stop at first solution

            # Select unassigned var with MRV
            unassigned = [v for v in variables if v not in assignment]
            # Compute domains
            domains = []
            for v in unassigned:
                dom = possible_positions(v)
                if not dom:
                    return False
                domains.append((len(dom), v, sorted(dom)))
            # Choose var with smallest domain
            domains.sort(key=lambda x: (x[0], x[1][0], x[1][1]))  # deterministic tie-break
            _, var, dom = domains[0]

            cat, val = var
            for pos in dom:
                assignment[var] = pos
                used_by_cat[cat].add(pos)
                if constraints_ok(assignment):
                    if backtrack():
                        return True
                used_by_cat[cat].remove(pos)
                del assignment[var]
            return False

        backtrack()
        return solutions[0] if solutions else None

    solution_assignment = solve()

    # Build output rows per house 1..4
    def value_at(cat, pos):
        for (c, v), p in solution_assignment.items():
            if c == cat and p == pos:
                return v
        return None

    header = ["House", "Name", "Flower", "Hobby", "Pet", "Color", "HouseStyle"]
    rows = []
    for i in range(4):
        row = [
            str(i + 1),
            value_at("Name", i),
            value_at("Flower", i),
            value_at("Hobby", i),
            value_at("Pet", i),
            value_at("Color", i),
            value_at("HouseStyle", i),
        ]
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
